package models

import (
	"fmt"
	"math"
	"strconv"
	"strings"

	"github.com/fullstack-lang/gong/app/xsd/tests/aixm/airspace/go/models/aixmdatatypes"
	"github.com/fullstack-lang/gong/app/xsd/tests/aixm/airspace/go/models/aixmfeatures"
	"github.com/fullstack-lang/gong/app/xsd/tests/aixm/airspace/go/models/gml"
	maplibre "github.com/fullstack-lang/gong/lib/maplibre/go/models"
)

type circleCenterInfo struct {
	Lat      float64
	Lon      float64
	RadiusNM float64
	IsArc    bool
}

func normalizeAirspaceKey(raw string) string {
	s := strings.ToLower(strings.TrimSpace(raw))
	s = strings.TrimPrefix(s, "#")
	s = strings.TrimPrefix(s, "urn:uuid:")
	s = strings.TrimPrefix(s, "uuid.")
	return s
}

func (stager *Stager) ux_maplibre() {
	if stager.maplibreStage == nil {
		return
	}

	// Preserve existing camera if user clicked on the map without requesting tree auto-focus
	var prevLat, prevLon, prevZoom, prevBearing float64
	hasPrevCamera := false
	if existingViews := stager.maplibreStage.GetInstancesSorted[*maplibre.MapView](); len(existingViews) > 0 {
		mv := existingViews[0]
		prevLat = mv.Latitude
		prevLon = mv.Longitude
		prevZoom = mv.Zoom
		prevBearing = mv.Bearing
		hasPrevCamera = prevZoom > 0
	}

	stager.maplibreStage.Reset()

	pitch := 15.0
	if stager.extrude3D {
		pitch = 52.0
	}

	mapView := &maplibre.MapView{
		Name:      "AIXM Aeronautical Map",
		StyleURL:  "offline",
		Latitude:  48.8566,
		Longitude: 2.3522,
		Zoom:      5.5,
		Pitch:     pitch,
		Bearing:   prevBearing,
	}

	layerTerritory := &maplibre.Layer{Name: "State / Territory Landmass", IsVisible: true}
	layerFIR := &maplibre.Layer{Name: "FIR / UIR / OCA", IsVisible: true}
	layerTMA := &maplibre.Layer{Name: "TMA / CTA / Sectors / Airways", IsVisible: true}
	layerCTR := &maplibre.Layer{Name: "CTR / ATZ / Aerodrome Zones", IsVisible: true}
	layerSpecial := &maplibre.Layer{Name: "Restricted / Danger / Special Use (P/R/D/TRA/TSA)", IsVisible: true}
	layerOther := &maplibre.Layer{Name: "Other Airspaces & Parts", IsVisible: true}
	layerBorders := &maplibre.Layer{Name: "GeoBorders & Curves", IsVisible: true}
	layerSelected := &maplibre.Layer{Name: "Selected Zone Highlight", IsVisible: true}
	layerMarkers := &maplibre.Layer{Name: "Airspace Labels & Navaid Centers (SVG)", IsVisible: true}

	var allCoords [][2]float64
	var selectedCoords [][2]float64

	visitedSurfaces := make(map[*aixmfeatures.SurfaceType]bool)
	visitedElevSurfaces := make(map[*aixmfeatures.ElevatedSurfaceType]bool)
	visitedCurves := make(map[*aixmfeatures.CurveType]bool)
	visitedElevCurves := make(map[*aixmfeatures.ElevatedCurveType]bool)

	if stager.stage.AixmfeaturesStage != nil {
		airspaces := stager.stage.AixmfeaturesStage.GetInstancesSorted[*aixmfeatures.AirspaceType]()
		authorities := stager.stage.AixmfeaturesStage.GetInstancesSorted[*aixmfeatures.AuthorityForAirspaceType]()
		airspaceByKey, authoritiesByAirspace := buildAirspaceAndAuthorityLookups(airspaces, authorities)

		for _, as := range airspaces {
			as := as
			if len(airspaces) > 150 && stager.hiddenAirspaces != nil && stager.hiddenAirspaces[as] {
				continue
			}
			for _, tsp := range as.TimeSlice {
				if tsp == nil || tsp.AirspaceTimeSlice == nil {
					continue
				}
				ts := tsp.AirspaceTimeSlice
				isSelected := stager.selectedAirspace == ts

				asType := ""
				if ts.Type_XSD != nil {
					asType = strings.TrimSpace(ts.Type_XSD.EnclosedText)
				}
				designator := ""
				if ts.Designator != nil {
					designator = strings.TrimSpace(ts.Designator.EnclosedText)
				}
				asName := ""
				for _, n := range ts.NameXSD {
					if n != nil && strings.TrimSpace(n.EnclosedText) != "" {
						asName = strings.TrimSpace(n.EnclosedText)
						break
					}
				}
				if designator == "" {
					designator = asName
				}
				if designator == "" {
					designator = as.Id
				}

				fillColor, strokeColor, fillOpacity, targetLayer := classifyAirspaceStyle(
					asType,
					layerFIR,
					layerTMA,
					layerCTR,
					layerSpecial,
					layerOther,
				)

				volIdx := 0
				hasMarkerForAirspace := false
				for _, gcp := range ts.GeometryComponent {
					if gcp == nil || gcp.AirspaceGeometryComponent == nil {
						continue
					}
					gc := gcp.AirspaceGeometryComponent
					if gc.TheAirspaceVolume == nil || gc.TheAirspaceVolume.AirspaceVolume == nil {
						continue
					}
					vol := gc.TheAirspaceVolume.AirspaceVolume

					lowerM, upperM := parseAirspaceAltitudeBoundsMeters(vol.LowerLimit, vol.UpperLimit, asType)
					limitsLabel := formatVerticalLimits(vol.LowerLimit, vol.UpperLimit)

					rings, centerLines, centers := extractVolumeGeometry(
						vol,
						airspaceByKey,
						visitedSurfaces,
						visitedElevSurfaces,
						visitedCurves,
						visitedElevCurves,
						0,
					)

					if stager.hiddenAirspaces != nil && stager.hiddenAirspaces[as] {
						continue
					}

					popup := fmt.Sprintf("<b>[%s] %s</b>", asType, designator)
					if asName != "" && asName != designator {
						popup += "<br/>" + asName
					}
					if limitsLabel != "" {
						popup += "<br/><small>" + limitsLabel + "</small>"
					}
					if authList := authoritiesByAirspace[as]; len(authList) > 0 {
						popup += "<br/><small><b>Authority:</b> " + formatAuthoritySummary(authList[0]) + "</small>"
					}

					onSelectAirspace := func() {
						stager.mu.Lock()
						defer stager.mu.Unlock()
						stager.selectedAirspace = ts
						stager.selectedGeoBorder = nil
						stager.focusOnSelected = false
						if stager.expandedAirspaces == nil {
							stager.expandedAirspaces = make(map[*aixmfeatures.AirspaceType]bool)
						}
						stager.expandedAirspaces[as] = true
						if stager.expandedCategories == nil {
							stager.expandedCategories = make(map[string]bool)
						}
						catKey := strings.ToUpper(strings.TrimSpace(asType))
						if catKey == "" {
							catKey = "OTHER"
						}
						stager.expandedCategories["AS_CAT_"+catKey] = true
						if stager.probeForm != nil {
							stager.probeForm.FillUpFormFromGongstruct(ts, "AirspaceTimeSliceType")
						}
						stager.ux_tree()
						stager.ux_maplibre()
					}

					for _, ring := range rings {
						if len(ring) < 3 {
							continue
						}
						volIdx++
						polyName := fmt.Sprintf("%s_%s_%d", designator, asType, volIdx)

						extrude := stager.extrude3D
						poly := &maplibre.Polygon{
							Name:            polyName,
							Label:           designator,
							PopupHTML:       popup,
							FillColor:       fillColor,
							FillOpacity:     fillOpacity,
							StrokeColor:     strokeColor,
							StrokeWidth:     2.4,
							StrokeOpacity:   0.96,
							IsExtruded:      extrude,
							BaseAltitude:    lowerM,
							ExtrusionHeight: upperM,
							OnClick: func(p *maplibre.Polygon) {
								onSelectAirspace()
							},
						}
						for ptIdx, pt := range ring {
							poly.Coordinates = append(poly.Coordinates, &maplibre.Coordinate{
								Name:      fmt.Sprintf("%s_pt_%d", polyName, ptIdx+1),
								Latitude:  pt[0],
								Longitude: pt[1],
							})
							allCoords = append(allCoords, pt)
							if isSelected {
								selectedCoords = append(selectedCoords, pt)
							}
						}
						targetLayer.Polygons = append(targetLayer.Polygons, poly)

						// If this airspace is selected, add a high-contrast highlighted polygon + perimeter outline on top
						if isSelected {
							hiPolyName := polyName + "_highlight"
							hiPoly := &maplibre.Polygon{
								Name:            hiPolyName,
								Label:           designator,
								PopupHTML:       popup,
								FillColor:       "#ffea00",
								FillOpacity:     0.36,
								StrokeColor:     "#ff3d00",
								StrokeWidth:     5.0,
								StrokeOpacity:   1.0,
								IsExtruded:      extrude,
								BaseAltitude:    lowerM,
								ExtrusionHeight: upperM + 50,
								OnClick: func(p *maplibre.Polygon) {
									onSelectAirspace()
								},
							}
							hiBorder := &maplibre.Polyline{
								Name:            polyName + "_highlight_border",
								Label:           designator,
								PopupHTML:       popup,
								StrokeColor:     "#ffff00",
								StrokeWidth:     2.4,
								StrokeOpacity:   1.0,
								StrokeDashArray: "4,2",
								OnClick: func(pl *maplibre.Polyline) {
									onSelectAirspace()
								},
							}
							for ptIdx, pt := range ring {
								hiPoly.Coordinates = append(hiPoly.Coordinates, &maplibre.Coordinate{
									Name:      fmt.Sprintf("%s_hpt_%d", hiPolyName, ptIdx+1),
									Latitude:  pt[0],
									Longitude: pt[1],
								})
								hiBorder.Coordinates = append(hiBorder.Coordinates, &maplibre.Coordinate{
									Name:      fmt.Sprintf("%s_hbpt_%d", hiPolyName, ptIdx+1),
									Latitude:  pt[0],
									Longitude: pt[1],
								})
							}
							// Ensure closed polyline loop for the perimeter highlight
							if len(ring) >= 3 && (ring[0][0] != ring[len(ring)-1][0] || ring[0][1] != ring[len(ring)-1][1]) {
								hiBorder.Coordinates = append(hiBorder.Coordinates, &maplibre.Coordinate{
									Name:      hiPolyName + "_hbpt_close",
									Latitude:  ring[0][0],
									Longitude: ring[0][1],
								})
							}
							layerSelected.Polygons = append(layerSelected.Polygons, hiPoly)
							layerSelected.Polylines = append(layerSelected.Polylines, hiBorder)
						}

						if !hasMarkerForAirspace {
							hasMarkerForAirspace = true
							cLat, cLon := computeRingCentroid(ring)
							badgeMarker := &maplibre.Marker{
								Name:              fmt.Sprintf("Label_%s_%s", designator, as.Name),
								Label:             designator,
								Latitude:          cLat,
								Longitude:         cLon,
								Color:             strokeColor,
								Scale:             1.0,
								Rotation:          0,
								RotationAlignment: maplibre.MarkerAlignmentViewport,
								PitchAlignment:    maplibre.MarkerAlignmentViewport,
								Anchor:            maplibre.MarkerAnchorCenter,
								IsDraggable:       false,
								PopupHTML:         popup,
								SVG:               buildAirspaceBadgeSVG(designator, asType, limitsLabel, strokeColor, isSelected),
								OnClick: func(m *maplibre.Marker) {
									onSelectAirspace()
								},
							}
							layerMarkers.Markers = append(layerMarkers.Markers, badgeMarker)
						}
					}

					// Render airway centrelines if present
					for clIdx, cl := range centerLines {
						if len(cl) < 2 {
							continue
						}
						clName := fmt.Sprintf("%s_centreline_%d", designator, clIdx+1)
						pl := &maplibre.Polyline{
							Name:            clName,
							Label:           designator,
							PopupHTML:       popup,
							StrokeColor:     strokeColor,
							StrokeWidth:     2.2,
							StrokeOpacity:   0.9,
							StrokeDashArray: "4,2",
							OnClick: func(p *maplibre.Polyline) {
								onSelectAirspace()
							},
						}
						for ptIdx, pt := range cl {
							pl.Coordinates = append(pl.Coordinates, &maplibre.Coordinate{
								Name:      fmt.Sprintf("%s_pt_%d", clName, ptIdx+1),
								Latitude:  pt[0],
								Longitude: pt[1],
							})
							allCoords = append(allCoords, pt)
							if isSelected {
								selectedCoords = append(selectedCoords, pt)
							}
						}
						targetLayer.Polylines = append(targetLayer.Polylines, pl)
					}

					for cIdx, ctr := range centers {
						kind := "Circle Center"
						if ctr.IsArc {
							kind = "Arc Center / Navaid"
						}
						navaidMarker := &maplibre.Marker{
							Name:              fmt.Sprintf("Center_%s_%d", designator, cIdx+1),
							Label:             designator,
							Latitude:          ctr.Lat,
							Longitude:         ctr.Lon,
							Color:             strokeColor,
							Scale:             1.0,
							Rotation:          0,
							RotationAlignment: maplibre.MarkerAlignmentMap,
							PitchAlignment:    maplibre.MarkerAlignmentViewport,
							Anchor:            maplibre.MarkerAnchorCenter,
							IsDraggable:       false,
							PopupHTML:         fmt.Sprintf("<b>%s</b><br/>%s (R=%.1f NM)", kind, designator, ctr.RadiusNM),
							SVG:               buildNavaidCenterSVG(designator, strokeColor),
							OnClick: func(m *maplibre.Marker) {
								onSelectAirspace()
							},
						}
						layerMarkers.Markers = append(layerMarkers.Markers, navaidMarker)
						allCoords = append(allCoords, [2]float64{ctr.Lat, ctr.Lon})
					}
				}
			}
		}

		// Extract GeoBorders
		borders := stager.stage.AixmfeaturesStage.GetInstancesSorted[*aixmfeatures.GeoBorderType]()
		for _, gb := range borders {
			gb := gb
			for _, tsp := range gb.TimeSlice {
				if tsp == nil || tsp.GeoBorderTimeSlice == nil {
					continue
				}
				ts := tsp.GeoBorderTimeSlice
				isSelected := stager.selectedGeoBorder == ts

				gbName := ""
				for _, n := range ts.NameXSD {
					if n != nil && strings.TrimSpace(n.EnclosedText) != "" {
						gbName = strings.TrimSpace(n.EnclosedText)
						break
					}
				}
				if gbName == "" {
					gbName = gb.Id
				}
				gbType := "BORDER"
				if ts.Type_XSD != nil && strings.TrimSpace(ts.Type_XSD.EnclosedText) != "" {
					gbType = strings.TrimSpace(ts.Type_XSD.EnclosedText)
				}

				if ts.Border != nil {
					if ts.Border.Curve != nil {
						visitedCurves[ts.Border.Curve] = true
					}
					if ts.Border.ElevatedCurve != nil {
						visitedElevCurves[ts.Border.ElevatedCurve] = true
					}
				}

				if stager.hiddenGeoBorders != nil && stager.hiddenGeoBorders[gb] {
					continue
				}

				onSelectBorder := func() {
					stager.mu.Lock()
					defer stager.mu.Unlock()
					stager.selectedGeoBorder = ts
					stager.selectedAirspace = nil
					stager.focusOnSelected = false
					if stager.probeForm != nil {
						stager.probeForm.FillUpFormFromGongstruct(ts, "GeoBorderTimeSliceType")
					}
					stager.ux_maplibre()
				}

				lines := extractCurvePropertyPolylines(ts.Border)
				for lIdx, line := range lines {
					if len(line) < 2 {
						continue
					}
					lineName := fmt.Sprintf("GeoBorder_%s_%d", gbName, lIdx+1)
					popup := fmt.Sprintf("<b>GeoBorder [%s]</b><br/>%s", gbType, gbName)

					// If this GeoBorder represents a STATE or COASTLINE territory (such as the fictitious Republic of Donlon island),
					// also render a landmass polygon on the bottom territory layer so the island/state is visible on the map.
					upperGBType := strings.ToUpper(gbType)
					if len(line) >= 4 && (upperGBType == "STATE" || upperGBType == "COASTLINE" || upperGBType == "TERRITORY") {
						terrName := fmt.Sprintf("Territory_%s_%d", gbName, lIdx+1)
						terrPoly := &maplibre.Polygon{
							Name:          terrName,
							Label:         gbName,
							PopupHTML:     popup,
							FillColor:     "#f1ede2",
							FillOpacity:   0.92,
							StrokeColor:   "#8d6e63",
							StrokeWidth:   2.0,
							StrokeOpacity: 0.9,
							OnClick: func(p *maplibre.Polygon) {
								onSelectBorder()
							},
						}
						for ptIdx, pt := range line {
							terrPoly.Coordinates = append(terrPoly.Coordinates, &maplibre.Coordinate{
								Name:      fmt.Sprintf("%s_pt_%d", terrName, ptIdx+1),
								Latitude:  pt[0],
								Longitude: pt[1],
							})
						}
						layerTerritory.Polygons = append(layerTerritory.Polygons, terrPoly)
					}

					pl := &maplibre.Polyline{
						Name:            lineName,
						Label:           gbName,
						StrokeColor:     "#ad1457",
						StrokeWidth:     2.8,
						StrokeOpacity:   0.94,
						StrokeDashArray: "6,4",
						PopupHTML:       popup,
						OnClick: func(p *maplibre.Polyline) {
							onSelectBorder()
						},
					}
					for ptIdx, pt := range line {
						pl.Coordinates = append(pl.Coordinates, &maplibre.Coordinate{
							Name:      fmt.Sprintf("%s_pt_%d", lineName, ptIdx+1),
							Latitude:  pt[0],
							Longitude: pt[1],
						})
						allCoords = append(allCoords, pt)
						if isSelected {
							selectedCoords = append(selectedCoords, pt)
						}
					}
					layerBorders.Polylines = append(layerBorders.Polylines, pl)

					if isSelected {
						hiLine := &maplibre.Polyline{
							Name:          lineName + "_highlight",
							Label:         gbName,
							StrokeColor:   "#ff3d00",
							StrokeWidth:   5.5,
							StrokeOpacity: 1.0,
							PopupHTML:     popup,
							OnClick: func(p *maplibre.Polyline) {
								onSelectBorder()
							},
						}
						for ptIdx, pt := range line {
							hiLine.Coordinates = append(hiLine.Coordinates, &maplibre.Coordinate{
								Name:      fmt.Sprintf("%s_hpt_%d", lineName, ptIdx+1),
								Latitude:  pt[0],
								Longitude: pt[1],
							})
						}
						layerSelected.Polylines = append(layerSelected.Polylines, hiLine)
					}

					if lIdx == 0 {
						midLat, midLon := computeRingCentroid(line)
						layerMarkers.Markers = append(layerMarkers.Markers, &maplibre.Marker{
							Name:              fmt.Sprintf("BorderLabel_%s", gb.Name),
							Label:             gbName,
							Latitude:          midLat,
							Longitude:         midLon,
							Color:             "#ad1457",
							Scale:             1.0,
							RotationAlignment: maplibre.MarkerAlignmentViewport,
							PitchAlignment:    maplibre.MarkerAlignmentViewport,
							Anchor:            maplibre.MarkerAnchorCenter,
							PopupHTML:         popup,
							SVG:               buildAirspaceBadgeSVG(gbName, gbType, "", "#ad1457", isSelected),
							OnClick: func(m *maplibre.Marker) {
								onSelectBorder()
							},
						})
					}
				}
			}
		}

		// Fallback for any standalone Surfaces or Curves in AixmfeaturesStage
		if len(airspaces) == 0 || len(stager.hiddenAirspaces) == 0 {
			for _, surf := range stager.stage.AixmfeaturesStage.GetInstancesSorted[*aixmfeatures.SurfaceType]() {
				if visitedSurfaces[surf] {
					continue
				}
				rings, _ := extractPatchesRingsAndCenters(surf.Patches, visitedCurves)
				for rIdx, ring := range rings {
					if len(ring) < 3 {
						continue
					}
					polyName := fmt.Sprintf("Surface_%s_%d", surf.Name, rIdx+1)
					poly := &maplibre.Polygon{
						Name:          polyName,
						Label:         "",
						FillColor:     "#6a1b9a",
						FillOpacity:   0.25,
						StrokeColor:   "#4a148c",
						StrokeWidth:   2.2,
						StrokeOpacity: 0.9,
						PopupHTML:     surf.Name,
					}
					for ptIdx, pt := range ring {
						poly.Coordinates = append(poly.Coordinates, &maplibre.Coordinate{
							Name:      fmt.Sprintf("%s_pt_%d", polyName, ptIdx+1),
							Latitude:  pt[0],
							Longitude: pt[1],
						})
						allCoords = append(allCoords, pt)
					}
					layerOther.Polygons = append(layerOther.Polygons, poly)
				}
			}

			for _, crv := range stager.stage.AixmfeaturesStage.GetInstancesSorted[*aixmfeatures.CurveType]() {
				if visitedCurves[crv] {
					continue
				}
				pts, _ := extractCurveSegmentsCoords(crv.Segments)
				if len(pts) >= 2 {
					pl := &maplibre.Polyline{
						Name:          "Curve_" + crv.Name,
						Label:         "",
						StrokeColor:   "#00838f",
						StrokeWidth:   2.2,
						StrokeOpacity: 0.9,
						PopupHTML:     crv.Name,
					}
					for ptIdx, pt := range pts {
						pl.Coordinates = append(pl.Coordinates, &maplibre.Coordinate{
							Name:      fmt.Sprintf("%s_pt_%d", crv.Name, ptIdx+1),
							Latitude:  pt[0],
							Longitude: pt[1],
						})
						allCoords = append(allCoords, pt)
					}
					layerBorders.Polylines = append(layerBorders.Polylines, pl)
				}
			}
		}
	}

	// Also render any standalone gml.PointType instances
	if stager.stage.GmlStage != nil {
		for _, pt := range stager.stage.GmlStage.GetInstancesSorted[*gml.PointType]() {
			if pt.Pos == nil {
				continue
			}
			pairs := parseLatLonPairs(pt.Pos.EnclosedText)
			if len(pairs) == 0 {
				continue
			}
			label := pt.Id
			if label == "" {
				label = pt.Name
			}
			layerMarkers.Markers = append(layerMarkers.Markers, &maplibre.Marker{
				Name:              "Point_" + pt.Name,
				Label:             label,
				Latitude:          pairs[0][0],
				Longitude:         pairs[0][1],
				Color:             "#0277bd",
				Scale:             1.0,
				RotationAlignment: maplibre.MarkerAlignmentViewport,
				PitchAlignment:    maplibre.MarkerAlignmentViewport,
				Anchor:            maplibre.MarkerAnchorCenter,
				PopupHTML:         "GML Point " + label,
				SVG:               buildNavaidCenterSVG(label, "#0277bd"),
			})
			allCoords = append(allCoords, pairs[0])
		}
	}

	candidateLayers := []*maplibre.Layer{
		layerTerritory,
		layerFIR,
		layerTMA,
		layerCTR,
		layerSpecial,
		layerOther,
		layerBorders,
		layerSelected,
		layerMarkers,
	}
	for _, l := range candidateLayers {
		if len(l.Polygons) > 0 || len(l.Polylines) > 0 || len(l.Markers) > 0 {
			mapView.Layers = append(mapView.Layers, l)
		}
	}

	if stager.focusOnSelected && len(selectedCoords) > 0 {
		cLat, cLon, zoom := computeViewportFromCoords(selectedCoords)
		mapView.Latitude = cLat
		mapView.Longitude = cLon
		mapView.Zoom = zoom
		stager.focusOnSelected = false
		stager.resetCameraToBounds = false
	} else if !stager.resetCameraToBounds && hasPrevCamera {
		mapView.Latitude = prevLat
		mapView.Longitude = prevLon
		mapView.Zoom = prevZoom
	} else if len(allCoords) > 0 {
		cLat, cLon, zoom := computeViewportFromCoords(allCoords)
		mapView.Latitude = cLat
		mapView.Longitude = cLon
		mapView.Zoom = zoom
		stager.resetCameraToBounds = false
	}

	stager.maplibreStage.StageBranch(mapView)
	stager.maplibreStage.Commit()
}

func extractVolumeGeometry(
	vol *aixmfeatures.AirspaceVolumeType,
	airspaceByKey map[string]*aixmfeatures.AirspaceType,
	visitedSurfaces map[*aixmfeatures.SurfaceType]bool,
	visitedElevSurfaces map[*aixmfeatures.ElevatedSurfaceType]bool,
	visitedCurves map[*aixmfeatures.CurveType]bool,
	visitedElevCurves map[*aixmfeatures.ElevatedCurveType]bool,
	depth int,
) (rings [][][2]float64, centerLines [][][2]float64, centers []circleCenterInfo) {
	if vol == nil || depth > 5 {
		return nil, nil, nil
	}

	// 1. Horizontal Projection (Surface / ElevatedSurface)
	if vol.HorizontalProjection != nil {
		if vol.HorizontalProjection.Surface != nil {
			visitedSurfaces[vol.HorizontalProjection.Surface] = true
		}
		if vol.HorizontalProjection.ElevatedSurface != nil {
			visitedElevSurfaces[vol.HorizontalProjection.ElevatedSurface] = true
		}
		r, c := extractSurfaceRingsAndCenters(vol.HorizontalProjection, visitedCurves)
		rings = append(rings, r...)
		centers = append(centers, c...)
	}

	// 2. Centreline + Width (Airways / Corridors)
	if vol.Centreline != nil {
		if vol.Centreline.Curve != nil {
			visitedCurves[vol.Centreline.Curve] = true
		}
		if vol.Centreline.ElevatedCurve != nil {
			visitedElevCurves[vol.Centreline.ElevatedCurve] = true
		}
		lines := extractCurvePropertyPolylines(vol.Centreline)
		widthNM := parseWidthNM(vol.Width)
		for _, cl := range lines {
			if len(cl) < 2 {
				continue
			}
			centerLines = append(centerLines, cl)
			corridorRing := buildCorridorPolygonFromCentreline(cl, widthNM)
			if len(corridorRing) >= 3 {
				rings = append(rings, corridorRing)
			}
		}
	}

	// 3. Contributor Airspace dependencies (<aixm:contributorAirspace>)
	if depProp := vol.ContributorAirspace; depProp != nil && depProp.AirspaceVolumeDependency != nil && depProp.AirspaceVolumeDependency.TheAirspace != nil {
		href := depProp.AirspaceVolumeDependency.TheAirspace.Href
		if href != "" {
			if contribAS := airspaceByKey[normalizeAirspaceKey(href)]; contribAS != nil {
				for _, tsp := range contribAS.TimeSlice {
					if tsp == nil || tsp.AirspaceTimeSlice == nil {
						continue
					}
					for _, gcp := range tsp.AirspaceTimeSlice.GeometryComponent {
						if gcp == nil || gcp.AirspaceGeometryComponent == nil ||
							gcp.AirspaceGeometryComponent.TheAirspaceVolume == nil ||
							gcp.AirspaceGeometryComponent.TheAirspaceVolume.AirspaceVolume == nil {
							continue
						}
						subR, subCL, subC := extractVolumeGeometry(
							gcp.AirspaceGeometryComponent.TheAirspaceVolume.AirspaceVolume,
							airspaceByKey,
							visitedSurfaces,
							visitedElevSurfaces,
							visitedCurves,
							visitedElevCurves,
							depth+1,
						)
						rings = append(rings, subR...)
						centerLines = append(centerLines, subCL...)
						centers = append(centers, subC...)
					}
				}
			}
		}
	}

	return rings, centerLines, centers
}

func parseWidthNM(w *aixmdatatypes.ValDistanceType) float64 {
	if w == nil || strings.TrimSpace(w.EnclosedText) == "" {
		return 5.0
	}
	val, err := strconv.ParseFloat(strings.TrimSpace(w.EnclosedText), 64)
	if err != nil || val <= 0 {
		return 5.0
	}
	uom := strings.ToUpper(strings.TrimSpace(w.Uom))
	switch uom {
	case "KM":
		return val / 1.852
	case "M":
		return val / 1852.0
	case "NM":
		return val
	default:
		return val
	}
}

func buildCorridorPolygonFromCentreline(line [][2]float64, widthNM float64) [][2]float64 {
	if len(line) < 2 {
		return nil
	}
	if widthNM <= 0 {
		widthNM = 5.0
	}
	halfDegLat := (widthNM * 0.5) / 60.0
	if halfDegLat < 0.02 {
		halfDegLat = 0.02
	}

	leftSide := make([][2]float64, 0, len(line))
	rightSide := make([][2]float64, 0, len(line))

	for i := 0; i < len(line); i++ {
		var dLat, dLon float64
		if i == 0 {
			dLat = line[1][0] - line[0][0]
			dLon = line[1][1] - line[0][1]
		} else if i == len(line)-1 {
			dLat = line[i][0] - line[i-1][0]
			dLon = line[i][1] - line[i-1][1]
		} else {
			dLat = line[i+1][0] - line[i-1][0]
			dLon = line[i+1][1] - line[i-1][1]
		}
		cosLat := math.Cos(line[i][0] * math.Pi / 180.0)
		if math.Abs(cosLat) < 0.1 {
			cosLat = 0.1
		}
		dx := dLon * cosLat
		dy := dLat
		norm := math.Hypot(dx, dy)
		if norm < 1e-9 {
			norm = 1.0
		}
		// Normal vector (-dy, dx)
		nx := -dy / norm
		ny := dx / norm

		offsetLat := ny * halfDegLat
		offsetLon := (nx * halfDegLat) / cosLat

		leftSide = append(leftSide, [2]float64{line[i][0] + offsetLat, line[i][1] + offsetLon})
		rightSide = append(rightSide, [2]float64{line[i][0] - offsetLat, line[i][1] - offsetLon})
	}

	ring := make([][2]float64, 0, len(leftSide)+len(rightSide)+1)
	ring = append(ring, leftSide...)
	for i := len(rightSide) - 1; i >= 0; i-- {
		ring = append(ring, rightSide[i])
	}
	ring = append(ring, leftSide[0])
	return ring
}

func classifyAirspaceStyle(
	asType string,
	layerFIR, layerTMA, layerCTR, layerSpecial, layerOther *maplibre.Layer,
) (fillColor, strokeColor string, fillOpacity float64, targetLayer *maplibre.Layer) {
	upper := strings.ToUpper(strings.TrimSpace(asType))
	switch upper {
	case "FIR", "FIR_P", "UIR", "UIR_P", "OCA", "NAS", "NO_FIR":
		return "#1e88e5", "#0d47a1", 0.14, layerFIR
	case "TMA", "TMA_P", "CTA", "CTA_P", "UTA", "SECTOR", "SECTOR_C", "AWY":
		return "#00acc1", "#006064", 0.24, layerTMA
	case "CTR", "ATZ", "HTZ", "PROTECT":
		return "#43a047", "#1b5e20", 0.32, layerCTR
	case "P", "R", "ADIZ":
		return "#e53935", "#b71c1c", 0.34, layerSpecial
	case "D", "D_OTHER", "TRA", "TSA", "CBA", "A", "OTHER:MOA":
		return "#fb8c00", "#e65100", 0.30, layerSpecial
	default:
		return "#8e24aa", "#4a148c", 0.22, layerOther
	}
}

func parseAirspaceAltitudeBoundsMeters(
	lower *aixmdatatypes.ValDistanceVerticalType,
	upper *aixmdatatypes.ValDistanceVerticalType,
	asType string,
) (lowerM float64, upperM float64) {
	lowerM = parseVerticalLimitMeters(lower, 0.0)
	defaultUpper := 3000.0
	switch strings.ToUpper(strings.TrimSpace(asType)) {
	case "FIR", "FIR_P", "UIR", "UIR_P", "OCA":
		defaultUpper = 6000.0
	case "CTR", "ATZ", "HTZ":
		defaultUpper = 1200.0
	case "TMA", "CTA":
		defaultUpper = 3500.0
	}
	upperM = parseVerticalLimitMeters(upper, lowerM+defaultUpper)
	if upperM <= lowerM {
		upperM = lowerM + 1000.0
	}
	if upperM > 15000.0 {
		upperM = 15000.0
	}
	return lowerM, upperM
}

func parseVerticalLimitMeters(v *aixmdatatypes.ValDistanceVerticalType, fallback float64) float64 {
	if v == nil {
		return fallback
	}
	txt := strings.ToUpper(strings.TrimSpace(v.EnclosedText))
	if txt == "" || txt == "GND" || txt == "SFC" || txt == "MSL" || txt == "FLOOR" {
		return 0.0
	}
	if txt == "UNL" || txt == "CEILING" || txt == "MAX" {
		return 12000.0
	}
	val, err := strconv.ParseFloat(txt, 64)
	if err != nil {
		return fallback
	}
	uom := strings.ToUpper(strings.TrimSpace(v.Uom))
	switch uom {
	case "FL":
		return val * 30.48 // 1 FL = 100 FT = 30.48 m
	case "FT":
		return val * 0.3048
	case "M":
		return val
	case "KM":
		return val * 1000.0
	default:
		if val <= 600 {
			return val * 30.48
		}
		return val * 0.3048
	}
}

func formatVerticalLimits(
	lower *aixmdatatypes.ValDistanceVerticalType,
	upper *aixmdatatypes.ValDistanceVerticalType,
) string {
	fmtOne := func(v *aixmdatatypes.ValDistanceVerticalType) string {
		if v == nil || strings.TrimSpace(v.EnclosedText) == "" {
			return ""
		}
		txt := strings.TrimSpace(v.EnclosedText)
		uom := strings.ToUpper(strings.TrimSpace(v.Uom))
		if uom == "FL" {
			return "FL" + txt
		}
		if uom != "" {
			return txt + " " + uom
		}
		return txt
	}
	l := fmtOne(lower)
	u := fmtOne(upper)
	if l != "" && u != "" {
		return l + " -> " + u
	}
	if u != "" {
		return "up to " + u
	}
	return l
}

func extractSurfaceRingsAndCenters(
	sp *aixmfeatures.SurfacePropertyType,
	visitedCurves map[*aixmfeatures.CurveType]bool,
) (rings [][][2]float64, centers []circleCenterInfo) {
	if sp == nil {
		return nil, nil
	}
	if sp.Surface != nil {
		r, c := extractPatchesRingsAndCenters(sp.Surface.Patches, visitedCurves)
		rings = append(rings, r...)
		centers = append(centers, c...)
	}
	if sp.ElevatedSurface != nil {
		r, c := extractPatchesRingsAndCenters(sp.ElevatedSurface.Patches, visitedCurves)
		rings = append(rings, r...)
		centers = append(centers, c...)
	}
	return rings, centers
}

func extractPatchesRingsAndCenters(
	patches *gml.SurfacePatchArrayPropertyType,
	visitedCurves map[*aixmfeatures.CurveType]bool,
) (rings [][][2]float64, centers []circleCenterInfo) {
	if patches == nil {
		return nil, nil
	}
	for _, pp := range patches.PolygonPatch {
		if pp == nil || pp.Exterior == nil {
			continue
		}
		ext := pp.Exterior
		if ext.LinearRing != nil {
			pts := parseDirectPositions(ext.LinearRing.Pos, ext.LinearRing.PosList, ext.LinearRing.PointProperty)
			if len(pts) >= 3 {
				rings = append(rings, pts)
			}
		}
		if ext.Ring != nil {
			var ringPts [][2]float64
			for _, cm := range ext.Ring.CurveMember {
				pts, ctrs := extractGMLCurvePropertyCoords(cm, visitedCurves)
				ringPts = append(ringPts, pts...)
				centers = append(centers, ctrs...)
			}
			if len(ringPts) >= 3 {
				rings = append(rings, ringPts)
			}
		}
	}
	return rings, centers
}

func extractCurvePropertyPolylines(cp *aixmfeatures.CurvePropertyType) [][][2]float64 {
	if cp == nil {
		return nil
	}
	var lines [][][2]float64
	if cp.Curve != nil {
		pts, _ := extractCurveSegmentsCoords(cp.Curve.Segments)
		if len(pts) >= 2 {
			lines = append(lines, pts)
		}
	}
	if cp.ElevatedCurve != nil {
		pts, _ := extractCurveSegmentsCoords(cp.ElevatedCurve.Segments)
		if len(pts) >= 2 {
			lines = append(lines, pts)
		}
	}
	return lines
}

func extractGMLCurvePropertyCoords(
	cp *gml.CurvePropertyType,
	visitedCurves map[*aixmfeatures.CurveType]bool,
) (pts [][2]float64, centers []circleCenterInfo) {
	if cp == nil {
		return nil, nil
	}
	if cp.Curve != nil {
		p, c := extractCurveSegmentsCoords(cp.Curve.Segments)
		pts = append(pts, p...)
		centers = append(centers, c...)
	}
	if cp.OrientableCurve != nil && cp.OrientableCurve.BaseCurve != nil {
		p, c := extractGMLCurvePropertyCoords(cp.OrientableCurve.BaseCurve, visitedCurves)
		pts = append(pts, p...)
		centers = append(centers, c...)
	}
	if cp.CompositeCurve != nil {
		for _, sub := range cp.CompositeCurve.CurveMember {
			p, c := extractGMLCurvePropertyCoords(sub, visitedCurves)
			pts = append(pts, p...)
			centers = append(centers, c...)
		}
	}
	return pts, centers
}

func extractCurveSegmentsCoords(segs *gml.CurveSegmentArrayPropertyType) (pts [][2]float64, centers []circleCenterInfo) {
	if segs == nil {
		return nil, nil
	}
	var chunks [][][2]float64

	for _, gs := range segs.GeodesicString {
		if gs == nil {
			continue
		}
		c := parseDirectPositions(gs.Pos, gs.PosList, gs.PointProperty)
		if len(c) > 0 {
			chunks = append(chunks, c)
		}
	}
	for _, ls := range segs.LineStringSegment {
		if ls == nil {
			continue
		}
		c := parseDirectPositions(ls.Pos, ls.PosList, ls.PointProperty)
		if len(c) > 0 {
			chunks = append(chunks, c)
		}
	}
	for _, g := range segs.Geodesic {
		if g == nil {
			continue
		}
		c := parseDirectPositions(g.Pos, g.PosList, g.PointProperty)
		if len(c) > 0 {
			chunks = append(chunks, c)
		}
	}
	for _, cir := range segs.CircleByCenterPoint {
		if cir == nil {
			continue
		}
		cPts, ctr, ok := sampleCircleByCenterPoint(cir)
		if ok {
			chunks = append(chunks, cPts)
			centers = append(centers, ctr)
		}
	}
	for _, arc := range segs.ArcByCenterPoint {
		if arc == nil {
			continue
		}
		aPts, ctr, ok := sampleArcByCenterPoint(arc)
		if ok {
			chunks = append(chunks, aPts)
			centers = append(centers, ctr)
		}
	}

	if len(chunks) == 0 {
		return nil, centers
	}
	if len(chunks) == 1 {
		return chunks[0], centers
	}

	used := make([]bool, len(chunks))
	used[0] = true
	pts = append(pts, chunks[0]...)
	for step := 1; step < len(chunks); step++ {
		tail := pts[len(pts)-1]
		bestIdx := -1
		bestDist := math.MaxFloat64
		for i, ch := range chunks {
			if used[i] || len(ch) == 0 {
				continue
			}
			head := ch[0]
			d := (tail[0]-head[0])*(tail[0]-head[0]) + (tail[1]-head[1])*(tail[1]-head[1])
			if d < bestDist {
				bestDist = d
				bestIdx = i
			}
		}
		if bestIdx < 0 {
			break
		}
		used[bestIdx] = true
		pts = append(pts, chunks[bestIdx]...)
	}

	return pts, centers
}

func sampleCircleByCenterPoint(cir *gml.CircleByCenterPointType) (pts [][2]float64, ctr circleCenterInfo, ok bool) {
	var posSlice []*gml.DirectPositionType
	if cir.Pos != nil {
		posSlice = append(posSlice, cir.Pos)
	}
	var ppSlice []*gml.PointPropertyType
	if cir.PointProperty != nil {
		ppSlice = append(ppSlice, cir.PointProperty)
	}
	centerCoords := parseDirectPositions(posSlice, cir.PosList, ppSlice)
	if len(centerCoords) == 0 {
		return nil, ctr, false
	}
	cLat, cLon := centerCoords[0][0], centerCoords[0][1]
	radiusNM := parseRadiusNM(cir.Radius)
	if radiusNM <= 0 {
		radiusNM = 10.0
	}

	const numSteps = 64
	pts = sampleGeodesicArc(cLat, cLon, radiusNM, 0.0, 360.0, numSteps)
	return pts, circleCenterInfo{
		Lat:      cLat,
		Lon:      cLon,
		RadiusNM: radiusNM,
		IsArc:    false,
	}, true
}

func sampleArcByCenterPoint(arc *gml.ArcByCenterPointType) (pts [][2]float64, ctr circleCenterInfo, ok bool) {
	var posSlice []*gml.DirectPositionType
	if arc.Pos != nil {
		posSlice = append(posSlice, arc.Pos)
	}
	var ppSlice []*gml.PointPropertyType
	if arc.PointProperty != nil {
		ppSlice = append(ppSlice, arc.PointProperty)
	}
	centerCoords := parseDirectPositions(posSlice, arc.PosList, ppSlice)
	if len(centerCoords) == 0 {
		return nil, ctr, false
	}
	cLat, cLon := centerCoords[0][0], centerCoords[0][1]
	radiusNM := parseRadiusNM(arc.Radius)
	if radiusNM <= 0 {
		radiusNM = 15.0
	}

	startDeg := 0.0
	endDeg := 90.0
	if arc.StartAngle != nil {
		if v, err := strconv.ParseFloat(strings.TrimSpace(arc.StartAngle.EnclosedText), 64); err == nil {
			startDeg = v
		}
	}
	if arc.EndAngle != nil {
		if v, err := strconv.ParseFloat(strings.TrimSpace(arc.EndAngle.EnclosedText), 64); err == nil {
			endDeg = v
		}
	}

	const numSteps = 36
	pts = sampleGeodesicArc(cLat, cLon, radiusNM, startDeg, endDeg, numSteps)
	return pts, circleCenterInfo{
		Lat:      cLat,
		Lon:      cLon,
		RadiusNM: radiusNM,
		IsArc:    true,
	}, true
}

func parseRadiusNM(r *gml.LengthType) float64 {
	if r == nil {
		return 10.0
	}
	val, err := strconv.ParseFloat(strings.TrimSpace(r.EnclosedText), 64)
	if err != nil || val <= 0 {
		return 10.0
	}
	if val > 500 {
		return val / 1852.0
	}
	return val
}

func sampleGeodesicArc(cLat, cLon, radiusNM, startDeg, endDeg float64, steps int) [][2]float64 {
	if steps < 4 {
		steps = 4
	}
	degLatRadius := radiusNM / 60.0
	cosLat := math.Cos(cLat * math.Pi / 180.0)
	if math.Abs(cosLat) < 0.05 {
		cosLat = 0.05
	}
	degLonRadius := degLatRadius / cosLat

	pts := make([][2]float64, 0, steps+1)
	for i := 0; i <= steps; i++ {
		t := float64(i) / float64(steps)
		angRad := (startDeg + t*(endDeg-startDeg)) * math.Pi / 180.0
		lat := cLat + degLatRadius*math.Cos(angRad)
		lon := cLon + degLonRadius*math.Sin(angRad)
		pts = append(pts, [2]float64{lat, lon})
	}
	return pts
}

func parseDirectPositions(
	posSlice []*gml.DirectPositionType,
	posList *gml.DirectPositionListType,
	pointProps []*gml.PointPropertyType,
) [][2]float64 {
	var coords [][2]float64
	for _, p := range posSlice {
		if p != nil && p.EnclosedText != "" {
			coords = append(coords, parseLatLonPairs(p.EnclosedText)...)
		}
	}
	for _, pp := range pointProps {
		if pp != nil && pp.Point != nil && pp.Point.Pos != nil {
			coords = append(coords, parseLatLonPairs(pp.Point.Pos.EnclosedText)...)
		}
	}
	if posList != nil && posList.EnclosedText != "" {
		coords = append(coords, parseLatLonPairs(posList.EnclosedText)...)
	}
	return coords
}

func parseLatLonPairs(text string) [][2]float64 {
	fields := strings.Fields(text)
	if len(fields) < 2 {
		return nil
	}
	out := make([][2]float64, 0, len(fields)/2)
	for i := 0; i+1 < len(fields); i += 2 {
		lat, err1 := strconv.ParseFloat(fields[i], 64)
		lon, err2 := strconv.ParseFloat(fields[i+1], 64)
		if err1 != nil || err2 != nil {
			continue
		}
		if math.Abs(lat) > 90.0 && math.Abs(lon) <= 90.0 {
			lat, lon = lon, lat
		}
		if lat >= -90.0 && lat <= 90.0 && lon >= -180.0 && lon <= 180.0 {
			out = append(out, [2]float64{lat, lon})
		}
	}
	return out
}

func computeRingCentroid(ring [][2]float64) (float64, float64) {
	if len(ring) == 0 {
		return 0, 0
	}
	n := len(ring)
	if n > 1 && math.Abs(ring[0][0]-ring[n-1][0]) < 1e-7 && math.Abs(ring[0][1]-ring[n-1][1]) < 1e-7 {
		n--
	}
	sumLat, sumLon := 0.0, 0.0
	for i := 0; i < n; i++ {
		sumLat += ring[i][0]
		sumLon += ring[i][1]
	}
	return sumLat / float64(n), sumLon / float64(n)
}

func computeViewportFromCoords(coords [][2]float64) (cLat, cLon, zoom float64) {
	if len(coords) == 0 {
		return 48.8566, 2.3522, 5.5
	}
	minLat, maxLat := coords[0][0], coords[0][0]
	minLon, maxLon := coords[0][1], coords[0][1]
	for _, c := range coords[1:] {
		if c[0] < minLat {
			minLat = c[0]
		}
		if c[0] > maxLat {
			maxLat = c[0]
		}
		if c[1] < minLon {
			minLon = c[1]
		}
		if c[1] > maxLon {
			maxLon = c[1]
		}
	}
	cLat = (minLat + maxLat) * 0.5
	cLon = (minLon + maxLon) * 0.5
	span := math.Max(maxLat-minLat, maxLon-minLon)
	switch {
	case span > 40:
		zoom = 3.2
	case span > 20:
		zoom = 4.2
	case span > 10:
		zoom = 5.0
	case span > 5:
		zoom = 6.0
	case span > 2:
		zoom = 7.2
	case span > 0.8:
		zoom = 8.5
	case span > 0.2:
		zoom = 10.0
	default:
		zoom = 11.5
	}
	return cLat, cLon, zoom
}

func buildAirspaceBadgeSVG(designator, asType, limitsLabel, color string, isSelected bool) string {
	esc := func(s string) string {
		s = strings.ReplaceAll(s, "&", "&amp;")
		s = strings.ReplaceAll(s, "<", "&lt;")
		s = strings.ReplaceAll(s, ">", "&gt;")
		s = strings.ReplaceAll(s, `"`, "&quot;")
		return s
	}
	title := designator
	if asType != "" && asType != designator {
		title = fmt.Sprintf("%s [%s]", designator, asType)
	}
	if len(title) > 22 {
		title = title[:22]
	}
	sub := limitsLabel
	if len(sub) > 24 {
		sub = sub[:24]
	}

	width := 124
	if len(title)*7+20 > width {
		width = len(title)*7 + 20
	}
	if len(sub)*6+20 > width {
		width = len(sub)*6 + 20
	}
	height := 36
	if sub == "" {
		height = 24
	}

	bgFill := "#ffffff"
	borderStroke := color
	borderWidth := "1.8"
	if isSelected {
		bgFill = "#fff9c4"
		borderStroke = "#ff3d00"
		borderWidth = "3.0"
	}

	if sub == "" {
		return fmt.Sprintf(
			`<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="%d" viewBox="0 0 %d %d">`+
				`<rect x="1" y="1" width="%d" height="%d" rx="4" fill="%s" fill-opacity="0.94" stroke="%s" stroke-width="%s"/>`+
				`<text x="%d" y="16" text-anchor="middle" font-family="monospace, sans-serif" font-size="11" font-weight="bold" fill="%s">%s</text>`+
				`</svg>`,
			width, height, width, height,
			width-2, height-2, bgFill, borderStroke, borderWidth,
			width/2, color, esc(title),
		)
	}

	return fmt.Sprintf(
		`<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="%d" viewBox="0 0 %d %d">`+
			`<rect x="1" y="1" width="%d" height="%d" rx="4" fill="%s" fill-opacity="0.94" stroke="%s" stroke-width="%s"/>`+
			`<text x="%d" y="14" text-anchor="middle" font-family="monospace, sans-serif" font-size="11" font-weight="bold" fill="%s">%s</text>`+
			`<line x1="6" y1="19" x2="%d" y2="19" stroke="%s" stroke-width="0.8" stroke-opacity="0.6"/>`+
			`<text x="%d" y="30" text-anchor="middle" font-family="monospace, sans-serif" font-size="9.5" fill="#263238">%s</text>`+
			`</svg>`,
		width, height, width, height,
		width-2, height-2, bgFill, borderStroke, borderWidth,
		width/2, color, esc(title),
		width-6, color,
		width/2, esc(sub),
	)
}

func buildNavaidCenterSVG(label, color string) string {
	return fmt.Sprintf(
		`<svg xmlns="http://www.w3.org/2000/svg" width="28" height="28" viewBox="0 0 28 28">`+
			`<polygon points="14,2 25,8 25,20 14,26 3,20 3,8" fill="#ffffff" fill-opacity="0.88" stroke="%s" stroke-width="2"/>`+
			`<circle cx="14" cy="14" r="3" fill="%s"/>`+
			`<line x1="14" y1="2" x2="14" y2="7" stroke="%s" stroke-width="1.5"/>`+
			`<line x1="14" y1="21" x2="14" y2="26" stroke="%s" stroke-width="1.5"/>`+
			`<line x1="2" y1="14" x2="7" y2="14" stroke="%s" stroke-width="1.5"/>`+
			`<line x1="21" y1="14" x2="26" y2="14" stroke="%s" stroke-width="1.5"/>`+
			`</svg>`,
		color, color, color, color, color, color,
	)
}
